<script setup lang="ts">
import { computed, ref } from 'vue'
import AppPage from '@/components/common/AppPage.vue'
import EmptyState from '@/components/common/EmptyState.vue'
import ReadonlyRichContent from '@/components/rich-content/ReadonlyRichContent.vue'
import { questionTypeLabels } from '@/types/exam'
import { useExamScenario, wrongBookItems } from '@/fixtures/ui-scenarios/exam'
const { scenario, loadScenario } = useExamScenario('exam-wrong-book')
const preview = ref(false)
const props = defineProps<{ query: Record<string, unknown> }>()
preview.value = true; loadScenario(props.query)
const filter = ref('全部')
const rows = computed(() => wrongBookItems.filter(row => filter.value === '全部' || questionTypeLabels[row.item.type].startsWith(filter.value)))
function goExam() { uni.reLaunch({ url: `/pages/exam/index${preview.value ? '?scenario=exam-center' : ''}` }) }
</script>
<template>
  <AppPage title="我的错题本" :back-target="`/pages/profile/index${preview ? '?scenario=profile-default' : ''}`" :history-first="false"><view class="wrong-filters"><text v-for="tab in [{ label: '全部', count: 12 }, { label: '单选', count: 5 }, { label: '多选', count: 4 }, { label: '判断', count: 3 }]" :key="tab.label" :class="{ active: filter === tab.label }" role="button" @click="filter = tab.label">{{ tab.label }} {{ tab.count }}</text></view><EmptyState v-if="scenario.state || !rows.length" :title="scenario.state === 'load-failed' ? '加载失败' : '暂无错题'" :description="scenario.state === 'load-failed' ? '网络连接异常，已加载内容不会丢失。' : '继续保持！完成考试后答错的题会出现在这里。'"><wd-button @click="scenario.state === 'load-failed' ? (scenario.state = undefined) : goExam()">{{ scenario.state === 'load-failed' ? '重新加载' : '去考试' }}</wd-button></EmptyState><template v-else><view v-for="row in rows" :key="row.item.id" class="wrong-card"><view class="wrong-card__head"><text>{{ questionTypeLabels[row.item.type] }}</text><text>{{ row.source }}</text><text>0 / {{ row.item.score }}</text></view><view class="wrong-card__stem"><ReadonlyRichContent :schema-version="2" :doc="row.item.stem" /></view><view v-for="(option, index) in row.item.options" :key="option.id" class="wrong-card__option" :class="{ 'wrong-card__option--right': row.correctOptionIds.includes(option.id), 'wrong-card__option--wrong': row.selectedOptionIds.includes(option.id) }"><text class="wrong-card__letter">{{ row.item.type === 'judgment' ? index === 0 ? '✓' : '✕' : String.fromCharCode(65 + index) }}</text><ReadonlyRichContent :schema-version="2" :doc="option.content" /><text v-if="row.correctOptionIds.includes(option.id) || row.selectedOptionIds.includes(option.id)" class="wrong-card__mark">{{ row.correctOptionIds.includes(option.id) ? '正确' : '你选' }}</text></view><view class="wrong-card__summary"><text>正确答案 {{ row.item.type === 'judgment' ? '错误' : 'B' }}</text><text>你的答案 {{ row.selectedOptionIds.length ? 'A' : '未作答' }}</text></view></view><text class="wrong-end">— 没有更多了 —</text></template></AppPage>
</template>
<style scoped>
.wrong-filters { display: flex; justify-content: space-between; gap: 8px; margin: 0 0 18px; font-size: 12px; color: var(--app-color-text-secondary); }.wrong-filters > text { padding: 8px 12px; border-radius: 18px; background: var(--app-color-surface); }.wrong-filters .active { color: var(--app-color-primary); background: var(--app-color-primary-soft); }.wrong-card { background: var(--app-color-surface); border: 1px solid var(--app-color-border); padding: 14px; border-radius: var(--app-radius-md); margin-bottom: 16px; }.wrong-card__head { display: flex; align-items: center; gap: 8px; color: var(--app-color-text-muted); font-size: 10px; }.wrong-card__head > text:first-child { color: var(--app-color-primary); background: var(--app-color-primary-soft); border-radius: 4px; padding: 3px 5px; white-space: nowrap; }.wrong-card__head > text:nth-child(2) { flex: 1; }.wrong-card__head > text:last-child { white-space: nowrap; color: var(--app-color-danger); }.wrong-card__stem { font-size: 15px; font-weight: 500; line-height: 1.6; margin: 16px 0; }.wrong-card__option { display: flex; gap: 10px; align-items: flex-start; border: 1px solid var(--app-color-border); border-radius: var(--app-radius-sm); padding: 10px; font-size: 12px; margin-top: 8px; }.wrong-card__option :deep(.readonly-content) { flex: 1; }.wrong-card__letter { flex: none; font-family: monospace; }.wrong-card__option--right { color: var(--app-color-success); background: var(--app-color-success-soft); border-color: var(--app-color-success); }.wrong-card__option--wrong { color: var(--app-color-danger); background: var(--app-color-danger-soft); border-color: var(--app-color-danger); }.wrong-card__mark { flex: none; font-size: 10px; }.wrong-card__summary { display: flex; justify-content: space-between; padding-top: 14px; margin-top: 14px; border-top: 1px solid var(--app-color-border); font-size: 11px; }.wrong-card__summary > text:first-child { color: var(--app-color-success); }.wrong-card__summary > text:last-child { color: var(--app-color-danger); }.wrong-end { display: block; padding: 16px; text-align: center; font-size: 11px; color: var(--app-color-text-muted); }
</style>
